25	    .sort((a, b) => SHOP_KEYS.indexOf(a.key) - SHOP_KEYS.indexOf(b.key))
26	    .flatMap((shop) => shop.products.slice(0, VISIBLE_PER_SHOP));
27	}
28	
29	export interface CatalogShop {
30	  adapter: ShopAdapter;
31	  snapshotKey: ShopKey;
32	}
33	
34	export interface CatalogServiceOptions {
35	  source: DataSource;
36	  shops: CatalogShop[];
37	  snapshots: SnapshotSource;
